import json
from datetime import datetime

class Product:
    """Product class with inventory management"""

    def __init__(self, product_id, name, price, stock=0, categories=[]):  # Bug: Mutable default
        self.product_id = product_id
        self.name = name
        self.price = price
        self.stock = stock
        self.categories = categories  # Bug: Will share categories across instances
        self.reviews = []

    def add_review(self, rating, comment)  # Bug: Missing colon
        """Add a product review"""
        if rating < 1 or rating > 5:
            raise ValueError("Rating must be between 1 and 5")

        review = {
            'rating': rating,
            'comment': comment,
            'date': datetime.now()
        }
        self.reviews.append(review
        return True  # Bug: Missing closing parenthesis above

    def get_average_rating(self):
        """Calculate average rating"""
        if len(self.reviews) == 0:  # Bug: Should check if not reviews
            return 0 / len(self.reviews)  # Bug: Division by zero

        total = sum([r['rating'] for r in self.reviews])
        return total / len(self.reviews)

    def apply_discount(self, percentage):
        """Apply discount to product price"""
        if percentage > 100:
            percentage = 100

        discount_amount = self.price * percentage / 100
        self.price = self.price - discount_amount
        return self.price

    def update_stock(self, quantity):
        """Update product stock"""
        self.stock = self.stock + quantity
        if self.stock < 0  # Bug: Missing colon
            print("Warning: Negative stock!")
        return self.stock

class ShoppingCart:
    """Shopping cart for managing customer purchases"""

    def __init__(self, customer_id):
        self.customer_id = customer_id
        self.items = {}
        self.total = 0

    def add_item(self, product, quantity=1):
        """Add item to cart"""
        if quantity <= 0:
            return False

        if product.stock < quantity:
            raise Exception("Insufficient stock")

        if product.product_id in self.items:
            self.items[product.product_id]['quantity'] += quantity
        else:
            self.items[product.product_id] = {
                'product': product,
                'quantity': quantity,
                'price': product.price
            }

        product.stock = product.stock - quantity  # Bug: Not using update_stock method
        self._calculate_total()
        return True

    def remove_item(self, product_id):
        """Remove item from cart"""
        if product_id in self.items:
            quantity = self.items[product_id]['quantity']
            product = self.items[product_id]['product']
            product.stock += quantity

            del self.items[product_id]
            self._calculate_total()
            return True
        return False

    def _calculate_total(self):
        """Calculate cart total"""
        self.total = 0
        for item in self.items.values():
            self.total += item['price'] * item['quantity']
        return self.total

    def apply_coupon(self, coupon_code, discount_percent):
        """Apply coupon code"""
        if coupon_code == ""  # Bug: Should check if not coupon_code
            return False

        discount = self.total * discount_percent / 100
        self.total = self.total - discount
        return self.total

class Order:
    """Order processing class"""

    def __init__(self, order_id, cart, shipping_address={})  # Bug: Mutable default
        self.order_id = order_id
        self.cart = cart
        self.shipping_address = shipping_address
        self.status = "pending"
        self.created_at = datetime.now()
        self.items = cart.items
        self.total = cart.total

    def validate_order(self):
        """Validate order before processing"""
        if len(self.items) == 0:
            return False

        for item_id, item in self.items.items():
            product = item['product']
            quantity = item['quantity']

            if product.stock < quantity  # Bug: Missing colon
                return False

        if self.total <= 0:
            return False

        return True

    def process_payment(self, payment_method, amount):
        """Process payment for order"""
        if amount < self.total:
            raise ValueError("Insufficient payment amount")

        # Bug: Using eval on user input
        calculated_amount = eval(f"{amount}")  # Bug: Dangerous eval

        if calculated_amount >= self.total:
            self.status = "paid"
            return True
        return False

    def calculate_shipping(self, weight, distance)
        """Calculate shipping cost"""  # Bug: Missing colon in function definition
        base_rate = 5.00
        weight_rate = 0.5
        distance_rate = 0.1

        shipping_cost = base_rate + (weight * weight_rate) + (distance * distance_rate
        return shipping_cost  # Bug: Missing closing parenthesis above

    def generate_invoice(self):
        """Generate order invoice"""
        invoice = {
            'order_id': self.order_id,
            'date': self.created_at,
            'items': [],
            'total': self.total
        }

        for item_id, item in self.items.items():
            invoice['items'].append({
                'product_id': item_id,
                'name': item['product'].name,
                'quantity': item['quantity'],
                'price': item['price']
            })

        return json.dumps(invoice)

